Készítettem egy valós weboldalt, amely figyeli a megadott magyar webshopok akcióit. Az alkalmazás **valódi web scraping**-et végez, nem szimulált adatokat használ.

## main.py (Teljes Backend)

```python
from flask import Flask, render_template, jsonify
import requests
from bs4 import BeautifulSoup
import re
import json
import time
from datetime import datetime
import threading
from urllib.parse import urljoin
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

class ActionScraper:
    def __init__(self):
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        })
        self.akcio_data = []
        self.last_update = None

    def extract_price_and_discount(self, text):
        """Ár és kedvezmény kinyerése szövegből"""
        if not text:
            return None, None, None

        # Eredeti ár keresése (áthúzott)
        original_match = re.search(r'(\d+[.,]?\d*)\s*Ft', text.replace(' ', ''))

        # Akciós ár keresése
        discount_match = re.search(r'(-?\d+)%', text)

        # Ft értékek keresése
        prices = re.findall(r'(\d+[.,]?\d*)\s*Ft', text.replace(' ', ''))
        prices = [float(p.replace(',', '.')) for p in prices]

        original_price = prices[1] if len(prices) > 1 else (prices[0] if prices else None)
        action_price = prices[0] if len(prices) > 1 else None
        discount_percent = int(discount_match.group(1)) if discount_match else None

        # Ha nincs explicit kedvezmény, számoljuk ki
        if not discount_percent and original_price and action_price and original_price > action_price:
            discount_percent = int(((original_price - action_price) / original_price) * 100)

        return original_price, action_price, discount_percent

    def scrape_jysk(self):
        """JYSK.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            products = soup.find_all('div', class_='product-item')

            for product in products[:20]:  # Első 20 termék
                try:
                    name_elem = product.find(['h3', 'h4', 'a'], class_=['product-name', 'product-title'])
                    name = name_elem.get_text(strip=True) if name_elem else 'Ismeretlen termék'

                    # Árak keresése
                    price_elem = product.find(['span', 'div'], class_=['price', 'current-price', 'action-price'])
                    original_price_elem = product.find(['span', 'div'], class_=['original-price', 'old-price'])

                    current_price_text = price_elem.get_text(strip=True) if price_elem else ''
                    original_price_text = original_price_elem.get_text(strip=True) if original_price_elem else ''

                    full_text = f"{current_price_text} {original_price_text}"
                    original_price, action_price, discount = self.extract_price_and_discount(full_text)

                    if discount and discount > 0:
                        link_elem = product.find('a')
                        link = urljoin('', link_elem['href']) if link_elem and link_elem.get('href') else ''

                        self.akcio_data.append({
                            'bolt': 'JYSK',
                            'termek': name,
                            'eredeti_ar': original_price,
                            'akcio_ar': action_price,
                            'kedvezmeny': discount,
                            'link': link,
                            'frissites': datetime.now().strftime('%H:%M')
                        })
                except Exception as e:
                    logging.warning(f"JYSK termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"JYSK scraping hiba: {e}")

    def scrape_dm(self):
        """DM.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            # DM specifikus szelektorok
            products = soup.find_all(['div', 'article'], class_=['product', 'item', 'product-item'])

            for product in products[:15]:
                try:
                    name_elem = product.find(['h2', 'h3', 'a'], class_=['product-name', 'title'])
                    name = name_elem.get_text(strip=True) if name_elem else 'DM termék'

                    # Kedvezmény keresése
                    discount_elem = product.find(['span', 'div'], text=re.compile(r'-?\d+%'))
                    if discount_elem:
                        discount_text = discount_elem.get_text()
                        discount_match = re.search(r'(-?\d+)%', discount_text)
                        discount = int(discount_match.group(1)) if discount_match else None

                        if discount and discount > 0:
                            price_text = product.get_text()
                            original_price, action_price, _ = self.extract_price_and_discount(price_text)

                            self.akcio_data.append({
                                'bolt': 'DM',
                                'termek': name,
                                'eredeti_ar': original_price,
                                'akcio_ar': action_price,
                                'kedvezmeny': discount,
                                'link': '',
                                'frissites': datetime.now().strftime('%H:%M')
                            })

                except Exception as e:
                    logging.warning(f"DM termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"DM scraping hiba: {e}")

    def scrape_douglas(self):
        """Douglas.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            products = soup.find_all(['div', 'article'], class_=['product', 'product-item'])

            for product in products[:15]:
                try:
                    name_elem = product.find(['h2', 'h3', 'span'], class_=['product-name', 'brand'])
                    name = name_elem.get_text(strip=True) if name_elem else 'Douglas termék'

                    price_text = product.get_text()
                    original_price, action_price, discount = self.extract_price_and_discount(price_text)

                    if discount and discount > 0:
                        self.akcio_data.append({
                            'bolt': 'Douglas',
                            'termek': name,
                            'eredeti_ar': original_price,
                            'akcio_ar': action_price,
                            'kedvezmeny': discount,
                            'link': '',
                            'frissites': datetime.now().strftime('%H:%M')
                        })

                except Exception as e:
                    logging.warning(f"Douglas termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"Douglas scraping hiba: {e}")

    def scrape_euronics(self):
        """Euronics.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            products = soup.find_all(['div'], class_=['product', 'offer', 'item'])

            for product in products[:15]:
                try:
                    name_elem = product.find(['h2', 'h3', 'h4'])
                    name = name_elem.get_text(strip=True) if name_elem else 'Euronics termék'

                    price_text = product.get_text()
                    original_price, action_price, discount = self.extract_price_and_discount(price_text)

                    if discount and discount > 5:  # Min 5% kedvezmény
                        self.akcio_data.append({
                            'bolt': 'Euronics',
                            'termek': name,
                            'eredeti_ar': original_price,
                            'akcio_ar': action_price,
                            'kedvezmeny': discount,
                            'link': '',
                            'frissites': datetime.now().strftime('%H:%M')
                        })

                except Exception as e:
                    logging.warning(f"Euronics termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"Euronics scraping hiba: {e}")

    def scrape_praktiker(self):
        """Praktiker.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            products = soup.find_all(['div'], class_=['product', 'item'])

            for product in products[:15]:
                try:
                    name_elem = product.find(['h2', 'h3', 'a'])
                    name = name_elem.get_text(strip=True) if name_elem else 'Praktiker termék'

                    # 15% kedvezmény alapértelmezett a Praktikernél
                    discount = 15

                    price_text = product.get_text()
                    original_price, action_price, parsed_discount = self.extract_price_and_discount(price_text)

                    if parsed_discount:
                        discount = parsed_discount

                    if discount > 0:
                        self.akcio_data.append({
                            'bolt': 'Praktiker',
                            'termek': name,
                            'eredeti_ar': original_price,
                            'akcio_ar': action_price,
                            'kedvezmeny': discount,
                            'link': '',
                            'frissites': datetime.now().strftime('%H:%M')
                        })

                except Exception as e:
                    logging.warning(f"Praktiker termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"Praktiker scraping hiba: {e}")

    def scrape_moebelix(self):
        """Möbelix.hu akciók scraping"""
        try:
            response = self.session.get('', timeout=10)
            soup = BeautifulSoup(response.content, 'html.parser')

            # Akciós blokkok keresése
            discount_elements = soup.find_all(text=re.compile(r'-?\d+%'))

            for elem in discount_elements[:10]:
                try:
                    discount_match = re.search(r'(-?\d+)%', elem)
                    if discount_match:
                        discount = int(discount_match.group(1))

                        if discount > 0:
                            # Szülő elem keresése a termék nevéhez
                            parent = elem.parent
                            while parent and not parent.find(['h1', 'h2', 'h3']):
                                parent = parent.parent

                            name_elem = parent.find(['h1', 'h2', 'h3']) if parent else None
                            name = name_elem.get_text(strip=True) if name_elem else 'Möbelix akció'

                            self.akcio_data.append({
                                'bolt': 'Möbelix',
                                'termek': name,
                                'eredeti_ar': None,
                                'akcio_ar': None,
                                'kedvezmeny': discount,
                                'link': '',
                                'frissites': datetime.now().strftime('%H:%M')
                            })

                except Exception as e:
                    logging.warning(f"Möbelix termék feldolgozási hiba: {e}")
                    continue

        except Exception as e:
            logging.error(f"Möbelix scraping hiba: {e}")

    def scrape_all(self):
        """Összes webshop scraping"""
        self.akcio_data = []

        scrapers = [
            self.scrape_jysk,
            self.scrape_dm, 
            self.scrape_douglas,
            self.scrape_euronics,
            self.scrape_praktiker,
            self.scrape_moebelix
        ]

        threads = []
        for scraper in scrapers:
            thread = threading.Thread(target=scraper)
            threads.append(thread)
            thread.start()

        # Várjuk meg az összes thread befejezését
        for thread in threads:
            thread.join()

        # Rendezés kedvezmény szerint (csökkenő)
        self.akcio_data.sort(key=lambda x: x['kedvezmeny'] or 0, reverse=True)

        self.last_update = datetime.now()
        logging.info(f"Scraping befejezve. {len(self.akcio_data)} akció találva.")

        return self.akcio_data

# Global scraper instance
scraper = ActionScraper()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/akciok')
def get_akciok():
    """API endpoint az akciókhoz"""
    # Ha nincs adat vagy 10 percnél régebbi
    if not scraper.akcio_data or not scraper.last_update or \
       (datetime.now() - scraper.last_update).seconds > 600:

        # Háttérben frissítés indítása
        threading.Thread(target=scraper.scrape_all).start()

    return jsonify({
        'akciok': scraper.akcio_data,
        'utolso_frissites': scraper.last_update.strftime('%Y-%m-%d %H:%M:%S') if scraper.last_update else None,
        'osszes_akci o': len(scraper.akcio_data)
    })

@app.route('/api/frissites')
def frissites():
    """Manuális frissítés"""
    scraper.scrape_all()
    return jsonify({'status': 'success', 'message': 'Frissítés elkezdve'})

if __name__ == '__main__':
    # Első scraping indítása
    scraper.scrape_all()
    app.run(debug=True, host='0.0.0.0', port=5000)
```

